export const FEATURE_DEFAULTS = { sec: 40, build: 1 };
// the assembly as windows of the build channel (0 = nothing here, 1 = all joined)
export const SCHEDULE = {
  fly: { dns: [0.0, 0.15], lb: [0.08, 0.24], "app-1": [0.17, 0.33], "app-2": [0.25, 0.41], db: [0.33, 0.49] },
  grow: [[0.5, 0.6], [0.58, 0.7], [0.62, 0.74], [0.72, 0.86], [0.78, 0.92]],
};
const FLY_TRAVEL = 760;
const win = (b, [a, z]) => Math.max(0, Math.min(1, (b - a) / (z - a)));
const easeOut = (x) => 1 - Math.pow(1 - x, 3);
export const FEATURE_KEYS = [{ key: "s", channel: "sec", name: "second", unit: "s", values: [40, 61, 80], ease: 0.3, verb: "plays the recording" }];

const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
// the recorded values at a (continuous) second: [health, cpu, rps] per station
export function stationsAt(sec) {
  const pt = RUN.points[clamp(Math.floor(sec), 1, RUN.points.length) - 1];
  const o = {};
  RUN.stations.forEach((id, i) => { const [h, cpu, rps] = pt[i]; o[id] = { h, cpu, rps, dead: h === 3 }; });
  return o;
}
const linkRps = (s, a, b) => Math.min(s[a].rps, s[b].rps);

export function featureValues(state, values) {
  const s = stationsAt(state.sec);
  const lb = Math.max(s.lb.rps, 1);
  const sh1 = linkRps(s, "lb", "app-1") / lb, sh2 = linkRps(s, "lb", "app-2") / lb;
  return {
    ...values,
    "app-1.needle": (s["app-1"].dead ? 0 : s["app-1"].cpu / 100) * 270,
    "app-2.needle": (s["app-2"].dead ? 0 : s["app-2"].cpu / 100) * 270,
    "db.needle": (s.db.cpu / 100) * 270,
    // the flap swings toward the outlet it closes: shut on a dead server's side
    "lb.flap": clamp((sh1 - sh2) * 30, -30, 30),
    "lb.share.1": sh1 * 34,
    "lb.share.2": sh2 * 34,
    ...Object.fromEntries(Object.entries(SCHEDULE.fly).map(([id, w]) => ["fly." + id, FLY_TRAVEL * (1 - easeOut(win(state.build ?? 1, w)))])),
  };
}

export function featureTravel(a, b) {
  return Math.max(Math.abs(b.sec - a.sec) * 8, Math.abs((b.build ?? 1) - (a.build ?? 1)) * FLY_TRAVEL * 2.2);
}

// ---- per-frame painting: assembly, electricity, light, and the recorded traffic ----
const CABLE_ENDS = [["dns", "lb", "resolve"], ["lb", "app-1", "ingress"], ["lb", "app-2", "ingress"], ["app-1", "db", "query"], ["app-2", "db", "query"]];
const SPARK = { resolve: "#f7dfa4", ingress: "#ffb070", query: "#f4b3a8" };
const LAMP = ["ok", "warn", "hot", "dead"];
const PULSE_SPEED = 7;
let PAINT = null;
function mulberry(seed) { return () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
function paintSetup(stage) {
  const byName = (n) => stage.querySelector('[data-name="' + n + '"]');
  const cables = CABLE_ENDS.map((c, ci) => {
    const segs = [];
    for (let j = 0; ; j++) { const el = byName("cable." + ci + "." + j); if (!el) break; segs.push(el); }
    return { ci, a: c[0], b: c[1], kind: c[2], segs, mat: segs.map(() => ""), shown: segs.map(() => true) };
  });
  const lamps = ["dns", "lb", "app-1", "app-2", "db"].map((id) => ({ id, el: byName(id + ".lamp"), mat: "" }));
  // film times of each join, found once from the timeline
  const joins = SCHEDULE.grow.map(() => Infinity);
  let tLight = Infinity;
  if (typeof at === "function" && typeof DURATION === "number") {
    for (let t = 0; t <= DURATION; t += 1 / 240) {
      const b = at(t).build ?? 1;
      SCHEDULE.grow.forEach((w, i) => { if (joins[i] === Infinity && b >= w[1]) joins[i] = t; });
    }
    tLight = Math.max(...joins);
  }
  // the film time the recording first reads a failed station (for the dying sparks)
  let tFail = Infinity;
  if (typeof at === "function" && typeof DURATION === "number") {
    for (let t = 0; t <= DURATION; t += 1 / 120) { if (Object.values(stationsAt(at(t).sec)).some((x) => x.dead)) { tFail = t; break; } }
  }
  // a module comes alive when its first input joins (DNS with its own output)
  const powerAt = { dns: joins[0], lb: joins[0], "app-1": joins[1], "app-2": joins[2], db: Math.min(joins[3], joins[4]) };
  const root = stage.closest(".mo");
  const fx = stage.querySelector("svg.fx");
  const under = stage.querySelector("svg.under");
  const flash = root.querySelector(".mo-flash");
  PAINT = { cables, lamps, joins, tLight, root, fx, flash, under, tFail, powerAt };
}
function setMat(o, i, el, m) { if (el && o[i] !== m) { el.setAttribute("data-mat", m); o[i] = m; } }
function show(c, j, on) { if (c.shown[j] !== on) { c.segs[j].style.opacity = on ? "" : "0"; c.shown[j] = on; } }

// a jagged arc between two screen points: the shape of a spark jumping a gap
function jag(p0, p1, rnd, amp, n = 9) {
  const dx = p1[0] - p0[0], dy = p1[1] - p0[1], L = Math.hypot(dx, dy) || 1, nx = -dy / L, ny = dx / L;
  let d = "M" + p0[0].toFixed(2) + " " + p0[1].toFixed(2);
  for (let i = 1; i < n; i++) { const f = i / n, o = (rnd() - 0.5) * 2 * amp * Math.sin(Math.PI * f); d += "L" + (p0[0] + dx * f + nx * o).toFixed(2) + " " + (p0[1] + dy * f + ny * o).toFixed(2); }
  return d + "L" + p1[0].toFixed(2) + " " + p1[1].toFixed(2);
}

export function paint(state, stage, corner) {
  if (!PAINT) paintSetup(stage);
  // t is film time (camera, joins, surge); state.clock is wall time on the live page, so traffic keeps flowing at rest
  const P = PAINT, t = state.t ?? 0, b = state.build ?? 1, s = stationsAt(state.sec);
  const view = state.view || viewOf(state), k = view.w / DATA.W;
  const scr = (name) => screenOf(about(view.M, DATA.anchors[name]));
  // dark until the last join; the light arrives with the surge
  const light = t >= P.tLight + 0.14;
  const theme = light ? "light" : "dark";
  if (P.root.dataset.theme !== theme) P.root.dataset.theme = theme;
  for (const L of P.lamps) { const m = t >= P.powerAt[L.id] ? LAMP[s[L.id].h] : "gunmetal"; if (L.el && L.mat !== m) { L.el.setAttribute("data-mat", m); L.mat = m; } }
  const clock = state.clock ?? t;
  let under = "";
  // soft contact shadows: a shaded ellipse under each module (no blur filter); wide and faint
  // while a module is in the air, tight once it lands
  for (const id of ["dns", "lb", "app-1", "app-2", "db"]) {
    const p = easeOut(win(b, SCHEDULE.fly[id])), g = DATA.anchors["gnd." + id], [hw, hd] = DATA.anchors["fp." + id];
    if (p <= 0) continue;
    const grow = 1 + (1 - p) * 1.6;
    let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
    for (const [dx, dy] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) {
      const q = screenOf(about(view.M, [g[0] + dx * hw * grow + 10, g[1] + dy * hd * grow + 8, 0]));
      x0 = Math.min(x0, q[0]); x1 = Math.max(x1, q[0]); y0 = Math.min(y0, q[1]); y1 = Math.max(y1, q[1]);
    }
    under += '<ellipse cx="' + ((x0 + x1) / 2).toFixed(1) + '" cy="' + ((y0 + y1) / 2).toFixed(1) + '" rx="' + ((x1 - x0) * 0.62).toFixed(1) + '" ry="' + ((y1 - y0) * 0.66).toFixed(1) + '" fill="url(#g-shadow)" style="opacity:' + ((light ? 0.55 : 0.8) * Math.pow(p, 1.4)).toFixed(3) + '"/>';
  }
  // halos behind modules: gold as each comes alive, red while a server is down, ember while saturated
  const halo = (id, grad, o, scale = 2.3) => {
    if (o <= 0.004) return;
    const c = screenOf(about(view.M, DATA.anchors[id])), [hw, hd] = DATA.anchors["fp." + id], r = Math.max(hw, hd) * BK * scale;
    under += '<ellipse cx="' + c[0].toFixed(1) + '" cy="' + c[1].toFixed(1) + '" rx="' + r.toFixed(1) + '" ry="' + (r * 0.72).toFixed(1) + '" fill="url(#' + grad + ')" style="opacity:' + Math.min(1, o).toFixed(3) + '"/>';
  };
  for (const id of ["dns", "lb", "app-1", "app-2", "db"]) {
    if (typeof HOVER !== "undefined" && HOVER === id) halo(id, "h-gold", light ? 0.55 : 0.8, 2.0);
    const dp = t - P.powerAt[id];
    if (dp >= 0 && dp < 1.4) halo(id, "h-gold", Math.sin((dp / 1.4) * Math.PI) * (light ? 0.6 : 0.95));
    if (s[id].dead) halo(id, "h-red", 0.7 + 0.3 * Math.sin(clock * 3.2), 2.4);
    else if (s[id].h === 2) halo(id, "h-ember", 0.6 + 0.2 * Math.sin(clock * 2.1), 2.3);
  }
  // gold dust: drawn on a plain canvas behind and in front of the parts (cheap, no DOM per mote)
  if (typeof drawDust === "function") drawDust(clock, light);
  if (P.under) {
    const html = '<defs><radialGradient id="g-shadow"><stop offset="0" stop-color="#2a1d12" stop-opacity=".5"/><stop offset=".6" stop-color="#2a1d12" stop-opacity=".18"/><stop offset="1" stop-color="#2a1d12" stop-opacity="0"/></radialGradient><radialGradient id="h-gold"><stop offset="0" stop-color="#f3d58e" stop-opacity=".75"/><stop offset=".5" stop-color="#e8b965" stop-opacity=".25"/><stop offset="1" stop-color="#e8b965" stop-opacity="0"/></radialGradient><radialGradient id="h-red"><stop offset="0" stop-color="#e2574c" stop-opacity=".7"/><stop offset=".55" stop-color="#d4524f" stop-opacity=".2"/><stop offset="1" stop-color="#d4524f" stop-opacity="0"/></radialGradient><radialGradient id="h-ember"><stop offset="0" stop-color="#f08a4b" stop-opacity=".6"/><stop offset=".55" stop-color="#e8692c" stop-opacity=".18"/><stop offset="1" stop-color="#e8692c" stop-opacity="0"/></radialGradient></defs>' + under;
    if (P.underHtml !== html) { P.under.innerHTML = html; P.underHtml = html; }
    P.under.style.setProperty("--k", k.toFixed(4));
    P.under.dataset.theme = light ? "light" : "dark";
  }

  let fx = "";
  for (const c of P.cables) {
    const n = c.segs.length, grow = win(b, SCHEDULE.grow[c.ci]);
    const shownCount = Math.round(grow * n);
    const joined = t >= P.joins[c.ci];
    const rate = Math.min(s[c.a].rps, s[c.b].rps), gap = rate > 0 ? Math.max(2, Math.min(12, Math.round(300 / rate))) : Infinity;
    // the surge: a bright head races along every cable when the last one joins
    const surge = (t - P.tLight) / 0.7, head = surge * n;
    c.segs.forEach((el, j) => {
      show(c, j, j < shownCount);
      let m = c.kind;
      if (surge >= 0 && surge <= 1.2 && Math.abs(j - head) < 1.6) m = c.kind + "-hi";
      else if (light && joined && isFinite(gap) && (((((state.clock ?? t) * PULSE_SPEED - j) % gap) + gap) % gap) < 1) m = c.kind + "-hi";
      setMat(c.mat, j, el, m);
    });
    // a growing cable carries a small live spark at its tip
    if (grow > 0 && grow < 1) {
      const from = scr("port." + c.ci + ".from"), to = scr("port." + c.ci + ".to");
      const tip = [from[0] + (to[0] - from[0]) * grow, from[1] + (to[1] - from[1]) * grow];
      const rnd = mulberry(c.ci * 977 + Math.floor(t * 30));
      for (let a = 0; a < 3; a++) { const ang = rnd() * Math.PI * 2, len = (10 + rnd() * 16) * k; fx += '<path d="' + jag(tip, [tip[0] + Math.cos(ang) * len, tip[1] + Math.sin(ang) * len], rnd, 4 * k, 6) + '" class="arc" style="--c:' + SPARK[c.kind] + '"/>'; }
      fx += '<circle cx="' + tip[0].toFixed(2) + '" cy="' + tip[1].toFixed(2) + '" r="' + (3.2 * k).toFixed(2) + '" class="core" style="--c:' + SPARK[c.kind] + '"/>';
    }
    // the join: a crackle jumps into the port and a ring opens around it
    const dt = t - P.joins[c.ci];
    if (dt >= 0 && dt < 0.75) {
      const to = scr("port." + c.ci + ".to"), life = 1 - dt / 0.75, rnd = mulberry(c.ci * 131 + Math.floor(t * 30));
      for (let a = 0; a < 8; a++) {
        const ang = rnd() * Math.PI * 2, len = (34 + rnd() * 56) * k * (0.5 + life);
        fx += '<path d="' + jag(to, [to[0] + Math.cos(ang) * len, to[1] + Math.sin(ang) * len], rnd, 9 * k, 11) + '" class="arc' + (a < 2 ? " big" : "") + '" style="--c:' + SPARK[c.kind] + ";opacity:" + life.toFixed(3) + '"/>';
      }
      for (const [r0, sp] of [[10, 140], [4, 80]]) fx += '<circle cx="' + to[0].toFixed(2) + '" cy="' + to[1].toFixed(2) + '" r="' + ((r0 + dt * sp) * k).toFixed(2) + '" class="ring" style="--c:' + SPARK[c.kind] + ";opacity:" + life.toFixed(3) + '"/>';
      fx += '<circle cx="' + to[0].toFixed(2) + '" cy="' + to[1].toFixed(2) + '" r="' + (7 * k * life).toFixed(2) + '" class="core" style="--c:' + SPARK[c.kind] + '"/>';
    }
  }
  // the surge: arcs leap between every pair of joined ports as the system comes alive
  const ds = t - P.tLight;
  if (ds >= 0 && ds < 1.1) {
    const life = 1 - ds / 1.1, rnd = mulberry(7 + Math.floor(t * 30));
    for (const c of P.cables) {
      const a = scr("port." + c.ci + ".from"), z = scr("port." + c.ci + ".to");
      for (let r = 0; r < 2; r++) { const d = jag(a, z, rnd, (22 + r * 14) * k * life, 18); fx += '<path d="' + d + '" class="halo" style="--c:' + SPARK[c.kind] + '"/><path d="' + d + '" class="arc big" style="--c:' + SPARK[c.kind] + ";opacity:" + (life * (1 - r * 0.35)).toFixed(3) + '"/>'; }
      for (const p of [a, z]) fx += '<circle cx="' + p[0].toFixed(2) + '" cy="' + p[1].toFixed(2) + '" r="' + ((8 + ds * 120) * k).toFixed(2) + '" class="ring" style="--c:' + SPARK[c.kind] + ";opacity:" + life.toFixed(3) + '"/>';
    }
  }
  // the cut: when a server dies, its severed connections fizzle out
  const df = t - P.tFail;
  if (df >= 0 && df < 1.1) {
    const life = 1 - df / 1.1, rnd = mulberry(4242 + Math.floor(t * 30));
    for (const name of ["port.2.to", "port.4.from"]) {
      const q = scr(name);
      for (let a = 0; a < 6; a++) { const ang = rnd() * Math.PI * 2, len = (8 + rnd() * 26) * k * life; fx += '<path d="' + jag(q, [q[0] + Math.cos(ang) * len, q[1] + Math.sin(ang) * len], rnd, 5 * k, 7) + '" class="arc" style="--c:#ff7a66;opacity:' + life.toFixed(3) + '"/>'; }
      fx += '<circle cx="' + q[0].toFixed(2) + '" cy="' + q[1].toFixed(2) + '" r="' + ((5 + df * 70) * k).toFixed(2) + '" class="ring" style="--c:#ff7a66;opacity:' + life.toFixed(3) + '"/>';
    }
  }
  // the shockwave: one thin gold ring sweeping the whole frame as the light arrives
  if (ds >= 0 && ds < 1.3) {
    const last = P.joins.indexOf(P.tLight), q = last >= 0 ? scr("port." + last + ".to") : [view.x + view.w / 2, view.y + view.h / 2];
    for (const [lag, w] of [[0, 1], [0.12, 0.6]]) {
      const d = ds - lag; if (d < 0) continue;
      fx += '<circle cx="' + q[0].toFixed(2) + '" cy="' + q[1].toFixed(2) + '" r="' + (d * view.w * 1.1).toFixed(1) + '" class="wave" style="--c:#f3d58e;opacity:' + (Math.max(0, 1 - d / 1.3) * w).toFixed(3) + '"/>';
    }
  }
  if (P.fx) { const html = fx; if (P.fxHtml !== html) { P.fx.innerHTML = html; P.fxHtml = html; } P.fx.style.setProperty("--k", k.toFixed(4)); P.fx.dataset.theme = light ? "light" : "dark"; }
  // the light wave from the last port covers the switch from dark to light
  if (P.flash) {
    const last = P.joins.indexOf(P.tLight);
    const o = ds < 0 ? 0 : ds < 0.14 ? ds / 0.14 : Math.max(0, 1 - (ds - 0.14) / 0.9);
    const p = last >= 0 ? scr("port." + last + ".to") : [view.x + view.w / 2, view.y + view.h / 2];
    P.flash.style.setProperty("--fx", (((p[0] - view.x) / view.w) * 100).toFixed(2) + "%");
    P.flash.style.setProperty("--fy", (((p[1] - view.y) / view.h) * 100).toFixed(2) + "%");
    P.flash.style.setProperty("--fr", (20 + Math.max(0, ds) * 160).toFixed(1) + "%");
    P.flash.style.opacity = o.toFixed(3);
  }
  if (corner) {
    const text = light ? "second " + Math.floor(state.sec) + " · " + ["lb", "app-1", "app-2", "db"].map((id) => id + " " + s[id].rps).join(" · ") + " rps" : "assembling · " + Math.round(b * 100) + "%";
    if (corner("readout").textContent !== text) corner("readout").textContent = text;
  }
}
